let url,
  Datatables = $("#Datatables").DataTable({
    responsive: true,
    scrollX: true,
    ajax: readUrl,
    columnDefs: [
      {
        searcable: false,
        orderable: false,
        targets: 0,
      },
    ],
    order: [[1, "asc"]],
    columns: [
      {
        data: "no",
      },
      {
        data: "no",
      },
      {
        data: "appkey",
      },
      {
        data: "authkey",
      },
      {
        data: "message",
      },
      {
        data: "vendor",
      },
      {
        data: null,
        title: "Action",
        render: function (data, type, row, meta) {
          return (
            '<button class="btn btn-sm btn-success" onclick="edit(' +
            data["no"] +
            ')">Edit</button> <button class="btn btn-sm btn-danger" onclick="remove(' +
            data["no"] +
            ')">Delete</button>'
          );
        },
      },
    ],
  });

function reloadTable() {
  Datatables.reloadTable;
  Datatables.ajax.reload();
}

function addData() {
  alert(addUrl);
  $.ajax({
    url: addUrl,
    type: "post",
    dataType: "json",
    data: $("#form").serialize(),
    success: (a) => {
      $(".modal").modal("hide");
      Swal.fire("Sukses", "Sukses Menambahkan Data", "success"), reloadTable();
    },
    error: (a) => {
      console.log(a);
    },
  });
}

function remove(e) {
  swal({
    title: "Hapus Data ?",
    text: "yakin data ini akan di hapus",
    icon: "warning",
    buttons: ["No", "Yes"],
    dangerMode: true,
  }).then(function (isConfirm) {
    if (isConfirm) {
      $.ajax({
        url: deleteUrl,
        type: "post",
        dataType: "json",
        data: {
          no: e,
        },
        success: () => {
          //alert("Data Berhasil Di hapus");
          Swal.fire("Sukses", "Sukses Menghapus Data", "success"),
            reloadTable();
        },
        error: function () {
          alert("Error occured");
        },
      });
    } else {
      swal("Cancelled", "File tidak jadi dihapus", "error");
    }
  });
}

function editData() {
  $.ajax({
    url: editUrl,
    type: "post",
    dataType: "json",
    data: $("#form").serialize(),
    success: () => {
      $(".modal").modal("hide"),
        Swal.fire("Sukses", "Sukses Mengedit Data", "success"),
        reloadTable();
    },
    error: (a) => {
      console.log(a);
    },
  });
}

function add() {
  (url = "add"),
    $(".modal-title").html("Add Data"),
    $('.modal button[type="submit"]').html("Add");
}
function edit(a) {
  $.ajax({
    url: getUrl,
    type: "get",
    dataType: "json",
    data: {
      no: a,
    },
    success: (a) => {
      $('[name="no"]').val(a.no),
        $('[name="appkey"]').val(a.appkey),
        $('[name="authkey"]').val(a.authkey),
        $('[name="message"]').val(a.message),
        $('[name="vendor"]').val(a.vendor),
        $(".modal").modal("show"),
        $(".modal-title").html("Edit Data"),
        $('.modal button[type="submit"]').html("Edit"),
        (url = "edit");
    },
    error: (a) => {
      console.log(a);
    },
  });
}

Datatables.on("order.dt search.dt", () => {
  Datatables.column(0, {
    search: "applied",
    order: "applied",
  })
    .nodes()
    .each((a, e) => {
      a.innerHTML = e + 1;
    });
}),
  $("#form").validate({
    errorElement: "span",
    errorPlacement: (a, e) => {
      a.addClass("invalid-feedback"), e.closest(".form-group").append(a);
    },
    submitHandler: () => {
      "edit" == url ? editData() : addData();
    },
  }),
  $(".modal").on("hidden.bs.modal", () => {
    $("#form")[0].reset(), $("#form").validate().resetForm();
  });
